                }
        } else {
                if (file_printf(ms, " %d.%d", desc / 100000,
                    desc / 1000 % 100) == -1)
                        return -1;
                if ((desc / 100 % 10 > 0) ||
                    (desc % 100000 / 100 == 0)) {
